import {icon} from './icons.js';
import {definition} from './engine.js';
import {editorState,layerFor,selectablePart} from './editor-state.js';
export function renderSceneTree(root,{model,selection,query='',collapsed,select,changeLayer,rename,isolated}){
 root.replaceChildren();const e=editorState(model),assigned=new Set(e.layers.flatMap(l=>l.partIds)),layers=[...e.layers,{id:'unassigned',name:'Ungrouped layer',visible:true,locked:false,partIds:model.parts.filter(p=>!assigned.has(p.id)).map(p=>p.id)}].filter(l=>l.partIds.length||l.id!=='unassigned');
 const button=(text,label,fn,cls='')=>{const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-label',label);b.title=label;b.className=cls;b.onclick=fn;return b;};
 const badge=()=>{const el=document.createElement('span');el.className='ground-badge';el.title='Locked: fixed position and orientation';el.innerHTML=icon('ground');return el;};
 const iconButton=(name,label,fn,pressed)=>{const b=button('',label,fn,'scene-icon');b.innerHTML=icon(name);b.setAttribute('aria-pressed',String(pressed));return b;};
 for(const layer of layers){const parts=model.parts.filter(p=>layer.partIds.includes(p.id)),header=document.createElement('div');header.className='scene-layer'+(!layer.visible?' muted':'');
 const toggle=button(collapsed.has(layer.id)?'▸':'▾',(collapsed.has(layer.id)?'Expand ':'Collapse ')+layer.name,()=>{collapsed.has(layer.id)?collapsed.delete(layer.id):collapsed.add(layer.id);render();});header.append(toggle);
 const name=button(layer.name+' · '+parts.length,'Select layer '+layer.name,event=>select(parts.filter(p=>selectablePart(model,p.id,isolated)).map(p=>p.id),event),'scene-name');name.ondblclick=()=>layer.id!=='unassigned'&&rename('layer',layer.id);if(parts.some(p=>p.grounded))name.append(badge());header.append(name);
 if(layer.id!=='unassigned'){header.append(iconButton(layer.visible?'eye':'eyeOff',(layer.visible?'Hide ':'Show ')+layer.name,()=>changeLayer(layer.id,{visible:!layer.visible}),layer.visible),iconButton(layer.locked?'ground':'unlock',(layer.locked?'Unlock editing: ':'Lock editing: ')+layer.name,()=>changeLayer(layer.id,{locked:!layer.locked}),layer.locked));}root.append(header);
 if(collapsed.has(layer.id)&&!query)continue;
 const grouped=new Set();for(const g of e.groups){const members=parts.filter(p=>g.partIds.includes(p.id));if(!members.length)continue;members.forEach(p=>grouped.add(p.id));const row=document.createElement('div');row.className='scene-group';row.append(button(collapsed.has(g.id)?'▸':'▾',(collapsed.has(g.id)?'Expand group ':'Collapse group ')+g.name,()=>{collapsed.has(g.id)?collapsed.delete(g.id):collapsed.add(g.id);render();}));const name=button(g.name+' · '+members.length,'Select group '+g.name,event=>select(g.partIds.filter(id=>selectablePart(model,id,isolated)),event),'scene-name');name.classList.toggle('active',members.every(p=>selection.has(p.id)));name.ondblclick=()=>rename('group',g.id);if(members.some(p=>p.grounded))name.append(badge());row.append(name);root.append(row);if(!collapsed.has(g.id)||query)for(const p of members)partRow(p,true);}
 for(const p of parts.filter(p=>!grouped.has(p.id)))partRow(p,false);
 }
 if(!model.parts.length){const p=document.createElement('p');p.className='empty-search';p.textContent='No parts yet. Choose a part from the library.';root.append(p);}
 function partRow(p,nested){const d=definition(p),i=model.parts.indexOf(p);if(query&&!`${d.name} #${i+1}`.toLowerCase().includes(query))return;const b=button('',`Select ${d.name} #${i+1}`,event=>select([p.id],event),'tree-row'+(selection.has(p.id)?' active':'')+(nested?' nested':''));b.disabled=!selectablePart(model,p.id,isolated);b.dataset.partId=p.id;const swatch=document.createElement('span');swatch.className='swatch';swatch.style.background=d.color;const name=document.createElement('span');name.className='tree-name';name.textContent=d.name;const n=document.createElement('span');n.className='part-number';n.textContent='#'+(i+1);if(p.grounded){b.classList.add('grounded');b.title='Locked: fixed position and orientation';b.setAttribute('aria-label',`Select ${d.name} #${i+1}, locked`);}b.append(swatch,n,name);if(p.grounded)b.append(badge());root.append(b);}
 function render(){renderSceneTree(root,{model,selection,query,collapsed,select,changeLayer,rename,isolated});}
}
